// Matriz: etapas del pipeline, usuarios y todas las oportunidades del pipeline "RsViajes Matriz"
const LOC = 'UIJiu5Wa9iPVzMpbaZcx', PIPE = 'QxW5mmE6EmqSIHnmsPBm';
const out = [
  { json: { agencia: 'matriz', method: 'GET', path: `/opportunities/pipelines?locationId=${LOC}`, ctx: { tipo: 'pipes' } } },
  { json: { agencia: 'matriz', method: 'GET', path: `/users/?locationId=${LOC}`, ctx: { tipo: 'users' } } },
];
for (let page = 1; page <= 30; page++)
  out.push({ json: { agencia: 'matriz', method: 'GET', path: `/opportunities/search?location_id=${LOC}&pipeline_id=${PIPE}&limit=100&page=${page}`, ctx: { tipo: 'opps', page } } });
return out;

// Reporte diario para María Luisa: leads asignados y ventas/reservas por agente (Matriz)
const SHEET_URL = 'https://docs.google.com/spreadsheets/d/19pNro6wPdm5L5JBRbe9q92g3el0mntzt6B8NfgSbehk/edit';
const PIPE = 'QxW5mmE6EmqSIHnmsPBm', DATOS = 1675396445, RES = 1;
let prueba = false;
try { prueba = $('Prueba (webhook)').isExecuted; } catch (e) {}
const PARA = prueba ? 'xzenauto@gmail.com' : 'maluisasalazar@rsviajes.com';
const MESES = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
const tz = 'America/Mexico_City';
const etapas = {}, usuarios = {}; let opps = [];
for (const it of $('GHL por agencia').all()) {
  const { ctx, res } = it.json;
  if (ctx.tipo === 'pipes') { for (const p of res.pipelines || []) if (p.id === PIPE) for (const s of p.stages || []) etapas[s.id] = s.name; }
  else if (ctx.tipo === 'users') { for (const u of res.users || []) usuarios[u.id] = u.name || `${u.firstName || ''} ${u.lastName || ''}`.trim(); }
  else opps = opps.concat(res.opportunities || []);
}
const vistos = new Set();
opps = opps.filter(o => o.pipelineId === PIPE && !vistos.has(o.id) && vistos.add(o.id));
if (!opps.length || !Object.keys(etapas).length) throw new Error('GHL no regresó oportunidades o etapas de Matriz');
const limpiaEtapa = (n) => String(n || 'Otra').replace(/[^\p{L}\p{N}\s.,()\/-]/gu, '').trim();
const resultado = (o, et) => o.status === 'won' || /anticipo|pagado|mañana sale|en destino|de regreso|ganado/i.test(et) ? 'Venta / reserva'
  : /cotizaci/i.test(et) ? 'Cotización' : /[uú]ltima oportunidad/i.test(et) ? 'Última oportunidad' : /perdido/i.test(et) ? 'Perdido' : 'Sin cotizar aún';
const ESTADO = { open: 'Abierta', won: 'Ganada', lost: 'Perdida', abandoned: 'Abandonada' };
const filas = opps.map(o => {
  const f = DateTime.fromISO(o.createdAt, { zone: 'utc' }).setZone(tz);
  const et = limpiaEtapa(etapas[o.pipelineStageId]);
  return { ms: f.toMillis(), fecha: f.toFormat('yyyy-MM-dd'), mes: `${MESES[f.month - 1]} ${f.year}`,
    agente: (usuarios[o.assignedTo] || (o.assignedTo ? 'Otro usuario' : 'Sin asignar')).trim(),
    res: resultado(o, et), etapa: et, estado: ESTADO[o.status] || o.status, monto: Number(o.monetaryValue) || 0, nombre: String(o.name || '') };
}).sort((a, b) => b.ms - a.ms);
// Agentes: los que tienen leads asignados, de más a menos; "Sin asignar" al final
const cuenta = {};
for (const r of filas) cuenta[r.agente] = (cuenta[r.agente] || 0) + 1;
const agentes = Object.keys(cuenta).filter(a => a !== 'Sin asignar').sort((a, b) => cuenta[b] - cuenta[a]);
if (cuenta['Sin asignar']) agentes.push('Sin asignar');
const hoy = DateTime.now().setZone(tz);
const meses = [2, 1, 0].map(k => { const m = hoy.minus({ months: k }); return `${MESES[m.month - 1]} ${m.year}`; });
const t = (s) => "'" + String(s);
const D = "'Datos GHL'!";
const fmtFecha = (ms) => DateTime.fromMillis(ms).setZone(tz).setLocale('es').toFormat("d 'de' LLLL 'de' yyyy");
const desde = fmtFecha(filas[filas.length - 1].ms), hasta = fmtFecha(filas[0].ms);
// ---- Hoja: Datos GHL
const datos = filas.map(r => [r.fecha, t(r.mes), t(r.agente), t(r.res), t(r.etapa), t(r.estado), r.monto, t(r.nombre)]);
// ---- Hoja: Resumen (fórmulas sobre Datos GHL)
const n = agentes.length, ri = 5, rt = ri + n; // fila del total
const res = [
  [t('Leads y ventas por agente · RS Viajes Matriz')],
  [t(`Fuente: GHL, pipeline «RsViajes Matriz». Oportunidades creadas del ${desde} al ${hasta}. Actualizado el ${fmtFecha(hoy.toMillis())} a las ${hoy.toFormat('HH:mm')}.`)],
  [t('Una venta o reserva cuenta cuando la oportunidad está en Con Anticipo, Pagado al completo, Mañana sale, En destino, De regreso o Cliente Ganado.')],
  ['Agente', 'Leads asignados', ...meses.map(t), 'Cotización', 'Última oportunidad', 'Venta / reserva', 'Monto vendido', 'Perdido', 'Sin cotizar aún', '% de venta'],
];
agentes.forEach((a, i) => {
  const r = ri + i;
  res.push([t(a), `=COUNTIFS(${D}$C:$C;$A${r})`,
    ...['C', 'D', 'E'].map(c => `=COUNTIFS(${D}$C:$C;$A${r};${D}$B:$B;${c}$4)`),
    ...['F', 'G', 'H'].map(c => `=COUNTIFS(${D}$C:$C;$A${r};${D}$D:$D;${c}$4)`),
    `=SUMIFS(${D}$G:$G;${D}$C:$C;$A${r};${D}$D:$D;$H$4)`,
    ...['J', 'K'].map(c => `=COUNTIFS(${D}$C:$C;$A${r};${D}$D:$D;${c}$4)`),
    `=IF(B${r}=0;0;H${r}/B${r})`]);
});
res.push(['Total', ...'BCDEFGHIJK'.split('').map(c => `=SUM(${c}${ri}:${c}${rt - 1})`), `=IF(B${rt}=0;0;H${rt}/B${rt})`]);
res.push([]);
res.push(['Detalle de ventas / reservas']);
res.push(['Fecha de alta', 'Mes', 'Agente asignado', 'Resultado', 'Etapa en GHL', 'Estado GHL', 'Monto', 'Oportunidad']);
res.push([`=IFERROR(FILTER(${D}A2:H;${D}D2:D=$H$4);"Sin ventas registradas")`]);
const valores = { valueInputOption: 'USER_ENTERED', data: [
  { range: "'Datos GHL'!A2", values: datos },
  { range: 'Resumen!A1', values: res.map(f => { const x = f.slice(); while (x.length < 12) x.push(''); return x; }) },
] };
// ---- Formato
const rgb = (h) => ({ red: parseInt(h.slice(1, 3), 16) / 255, green: parseInt(h.slice(3, 5), 16) / 255, blue: parseInt(h.slice(5, 7), 16) / 255 });
const rg = (s, r0, r1, c0, c1) => ({ sheetId: s, startRowIndex: r0, endRowIndex: r1, startColumnIndex: c0, endColumnIndex: c1 });
const rep = (range, f, fields) => ({ repeatCell: { range, cell: { userEnteredFormat: f }, fields } });
const AZUL = rgb('#1F3864'), BLANCO = rgb('#FFFFFF'), GRIS = rgb('#BFBFBF');
const encab = { textFormat: { bold: true, fontFamily: 'Arial', foregroundColor: BLANCO }, backgroundColor: AZUL };
const ENT = { type: 'NUMBER', pattern: '#,##0;(#,##0);"-"' }, PESOS = { type: 'NUMBER', pattern: '$#,##0;($#,##0);"-"' };
const b = { style: 'SOLID', color: GRIS };
const fe = rt - 1; // índice 0 de la fila del total
const requests = [
  rep(rg(RES, 0, 1000, 0, 26), {}, 'userEnteredFormat'),
  rep(rg(RES, 0, 1, 0, 12), { textFormat: { bold: true, fontSize: 14, fontFamily: 'Arial' } }, 'userEnteredFormat.textFormat'),
  rep(rg(RES, 1, 3, 0, 12), { textFormat: { italic: true, fontFamily: 'Arial', foregroundColor: rgb('#595959') } }, 'userEnteredFormat.textFormat'),
  rep(rg(RES, 3, 4, 0, 12), { ...encab, horizontalAlignment: 'CENTER', verticalAlignment: 'MIDDLE', wrapStrategy: 'WRAP' }, 'userEnteredFormat'),
  rep(rg(RES, 4, fe, 0, 12), { textFormat: { fontFamily: 'Arial' } }, 'userEnteredFormat.textFormat'),
  rep(rg(RES, 4, fe, 1, 8), { numberFormat: ENT, horizontalAlignment: 'CENTER' }, 'userEnteredFormat.numberFormat,userEnteredFormat.horizontalAlignment'),
  rep(rg(RES, 4, fe, 9, 11), { numberFormat: ENT, horizontalAlignment: 'CENTER' }, 'userEnteredFormat.numberFormat,userEnteredFormat.horizontalAlignment'),
  rep(rg(RES, 4, fe, 8, 9), { numberFormat: PESOS }, 'userEnteredFormat.numberFormat'),
  rep(rg(RES, 4, fe, 11, 12), { numberFormat: { type: 'NUMBER', pattern: '0.0%' }, horizontalAlignment: 'CENTER' }, 'userEnteredFormat.numberFormat,userEnteredFormat.horizontalAlignment'),
  rep(rg(RES, 4, fe, 7, 9), { textFormat: { bold: true, fontFamily: 'Arial' }, backgroundColor: rgb('#E2EFDA') }, 'userEnteredFormat.textFormat,userEnteredFormat.backgroundColor'),
];
requests.push(
  rep(rg(RES, fe, fe + 1, 0, 12), { textFormat: { bold: true, fontFamily: 'Arial' }, backgroundColor: rgb('#D9D9D9'), horizontalAlignment: 'CENTER' }, 'userEnteredFormat.textFormat,userEnteredFormat.backgroundColor,userEnteredFormat.horizontalAlignment'),
  rep(rg(RES, fe, fe + 1, 0, 1), { horizontalAlignment: 'LEFT' }, 'userEnteredFormat.horizontalAlignment'),
  rep(rg(RES, fe, fe + 1, 1, 8), { numberFormat: ENT }, 'userEnteredFormat.numberFormat'),
  rep(rg(RES, fe, fe + 1, 9, 11), { numberFormat: ENT }, 'userEnteredFormat.numberFormat'),
  rep(rg(RES, fe, fe + 1, 8, 9), { numberFormat: PESOS }, 'userEnteredFormat.numberFormat'),
  rep(rg(RES, fe, fe + 1, 11, 12), { numberFormat: { type: 'NUMBER', pattern: '0.0%' } }, 'userEnteredFormat.numberFormat'),
  { updateBorders: { range: rg(RES, 3, fe + 1, 0, 12), top: b, bottom: b, left: b, right: b, innerHorizontal: b, innerVertical: b } },
  rep(rg(RES, fe + 2, fe + 3, 0, 8), { textFormat: { bold: true, fontSize: 12, fontFamily: 'Arial' } }, 'userEnteredFormat.textFormat'),
  rep(rg(RES, fe + 3, fe + 4, 0, 8), encab, 'userEnteredFormat.textFormat,userEnteredFormat.backgroundColor'),
  rep(rg(RES, fe + 4, 1000, 0, 1), { numberFormat: { type: 'DATE', pattern: 'yyyy-mm-dd' } }, 'userEnteredFormat.numberFormat'),
  rep(rg(RES, fe + 4, 1000, 6, 7), { numberFormat: PESOS }, 'userEnteredFormat.numberFormat'),
  rep(rg(DATOS, 1, 100000, 0, 1), { numberFormat: { type: 'DATE', pattern: 'yyyy-mm-dd' } }, 'userEnteredFormat.numberFormat'),
  rep(rg(DATOS, 1, 100000, 6, 7), { numberFormat: PESOS }, 'userEnteredFormat.numberFormat'),
  { updateSheetProperties: { properties: { sheetId: RES, gridProperties: { frozenRowCount: 4 } }, fields: 'gridProperties.frozenRowCount' } },
  { setBasicFilter: { filter: { range: { sheetId: DATOS, startRowIndex: 0, startColumnIndex: 0, endColumnIndex: 8 } } } },
);
// ---- Correo
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const pesos = (v) => '$' + Math.round(v).toLocaleString('en-US');
const pct = (a, b) => b ? (100 * a / b).toFixed(1) + '%' : '0.0%';
const resumen = agentes.map(a => {
  const fs = filas.filter(r => r.agente === a), v = fs.filter(r => r.res === 'Venta / reserva');
  return { a, leads: fs.length, m: meses.map(m => fs.filter(r => r.mes === m).length), cot: fs.filter(r => r.res === 'Cotización').length,
    ventas: v.length, monto: v.reduce((s, r) => s + r.monto, 0) };
});
const tot = { leads: filas.length, m: meses.map((_, i) => resumen.reduce((s, r) => s + r.m[i], 0)), cot: resumen.reduce((s, r) => s + r.cot, 0),
  ventas: resumen.reduce((s, r) => s + r.ventas, 0), monto: resumen.reduce((s, r) => s + r.monto, 0) };
const td = 'style="padding:6px 10px;border:1px solid #d0d0d0;text-align:center"', tdl = 'style="padding:6px 10px;border:1px solid #d0d0d0"';
const th = 'style="padding:6px 10px;border:1px solid #d0d0d0;background:#1F3864;color:#fff"';
const fila = (r, neg) => `<tr${neg ? ' style="font-weight:bold;background:#eee"' : ''}><td ${tdl}>${esc(r.a)}</td><td ${td}>${r.leads}</td>${r.m.map(x => `<td ${td}>${x}</td>`).join('')}<td ${td}>${r.cot}</td><td ${td}><b>${r.ventas}</b></td><td ${td}>${pesos(r.monto)}</td><td ${td}>${pct(r.ventas, r.leads)}</td></tr>`;
const ventas = filas.filter(r => r.res === 'Venta / reserva');
const tVentas = ventas.length ? `<table style="border-collapse:collapse;font-size:13px"><tr><th ${th}>Fecha de alta</th><th ${th}>Agente</th><th ${th}>Cliente</th><th ${th}>Etapa</th><th ${th}>Monto</th></tr>${ventas.map(r => `<tr><td ${tdl}>${r.fecha}</td><td ${tdl}>${esc(r.agente)}</td><td ${tdl}>${esc(r.nombre)}</td><td ${tdl}>${esc(r.etapa)}</td><td ${td}>${pesos(r.monto)}</td></tr>`).join('')}</table>` : '<p>No hay ventas o reservas registradas en GHL.</p>';
const html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#222">
<p>Hola María Luisa,</p>
<p>Este es el reporte de leads y ventas por agente de RS Viajes Matriz, con datos de GHL al ${fmtFecha(hoy.toMillis())} a las ${hoy.toFormat('HH:mm')}.</p>
<table style="border-collapse:collapse;font-size:13px"><tr><th ${th}>Agente</th><th ${th}>Leads asignados</th>${meses.map(m => `<th ${th}>${esc(m)}</th>`).join('')}<th ${th}>En cotización</th><th ${th}>Ventas / reservas</th><th ${th}>Monto vendido</th><th ${th}>% de venta</th></tr>
${resumen.map(r => fila(r)).join('')}${fila({ a: 'Total', ...tot }, true)}</table>
<p style="color:#666;font-size:12px">Leads asignados: oportunidades creadas desde el ${desde}. Una venta o reserva cuenta cuando la oportunidad está en Con Anticipo, Pagado al completo, Mañana sale, En destino, De regreso o Cliente Ganado. Si una venta no aparece, hay que mover la oportunidad a esa etapa en GHL.</p>
<h3 style="font-size:15px">Ventas y reservas</h3>${tVentas}
<p><a href="${SHEET_URL}">Ver la hoja completa</a> (cada oportunidad, con filtros).</p>
<p>Saludos,<br>Xzen Auto</p></div>`;
return [{ json: { para: PARA, asunto: `${prueba ? '[PRUEBA] ' : ''}Reporte de agentes RS Viajes Matriz · ${hoy.setLocale('es').toFormat("d 'de' LLLL")}`, html,
  valores, formato: { requests }, oportunidades: filas.length } }];
